package cn.course.community;
import java.util.*;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.test.web.servlet.MockMvc;
import org.springframework.transaction.annotation.Transactional;
import com.fasterxml.jackson.databind.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@SpringBootTest(properties={"spring.datasource.url=jdbc:h2:mem:evidence-workbench;MODE=MySQL;DATABASE_TO_LOWER=TRUE;DB_CLOSE_DELAY=-1","app.seed=true","app.seed-password=TestOnly!2026Long"})
@AutoConfigureMockMvc @Transactional
class EvidenceWorkbenchTest {
 @Autowired MockMvc mvc;@Autowired ObjectMapper json;@Autowired Store s;@Autowired CommunityService domain;@Autowired EvidenceWorkbench w;
 long uid(String n){return s.uid(n+"@example.test");}long add(String state){return s.insert("INSERT INTO evidence(submission_id,paragraph_id,source_title,source_url,excerpt,claim_text,state) VALUES(2,'p-gap','来源100%样本','https://example.test/source','测试引用材料','功能验收论断',?)",state);}void decide(long id,String who,String verdict,String reason,int count,int status)throws Exception{mvc.perform(post("/api/evidence/"+id+"/decisions").with(user(who+"@example.test")).with(csrf()).contentType("application/json").content(json.writeValueAsString(Map.of("verdict",verdict,"reason",reason,"expectedCount",count)))).andExpect(status().is(status));}
 @Test void rosterSafePagedCounts()throws Exception{add("DISPUTED");mvc.perform(get("/api/courses/1/evidence-workbench").with(user("teacher@example.test"))).andExpect(status().isOk()).andExpect(jsonPath("total").value(2)).andExpect(jsonPath("items[0].state").value("DISPUTED")).andExpect(jsonPath("pageSize").value(20));var r=w.list(1,uid("teacher"),"","","ALL",0,1);assertFalse(r.toString().contains("password"));assertFalse(r.toString().contains("draft_json"));}
 @Test void unauthorizedAndCrossCourseDenied()throws Exception{mvc.perform(get("/api/courses/1/evidence-workbench")).andExpect(status().isUnauthorized());for(String path:List.of("/api/courses/1/evidence-workbench","/api/evidence/1/review"))mvc.perform(get(path).with(user("outsider@example.test"))).andExpect(status().isForbidden());}
 @Test void detailOnlySharesReferencedParagraphNotFullPrivateSubmission()throws Exception{long id=add("PENDING");mvc.perform(get("/api/evidence/"+id+"/review").with(user("student@example.test"))).andExpect(status().isOk()).andExpect(jsonPath("can_read_submission").value(false)).andExpect(jsonPath("paragraph_text").isNotEmpty()).andExpect(jsonPath("content_json").doesNotExist()).andExpect(jsonPath("feedback").doesNotExist());mvc.perform(get("/api/submissions/2").with(user("student@example.test"))).andExpect(status().isForbidden());}
 @Test void authorCanReadDetailButCannotSelfVerify()throws Exception{long id=add("PENDING");var d=w.detail(id,uid("peer"));assertEquals(false,d.get("can_verify"));assertEquals(true,d.get("can_read_submission"));decide(id,"peer","PASS","作者不可自核",0,403);}
 @Test void teacherAndAssistantCanReadSubmissionContext(){long id=add("PENDING");assertEquals(true,w.detail(id,uid("teacher")).get("can_read_submission"));s.db.update("UPDATE course_member SET role='ASSISTANT' WHERE course_id=1 AND user_id=?",uid("student"));assertEquals(true,w.detail(id,uid("student")).get("can_read_submission"));}
 @Test void searchLiteralWildcardsAndAuthorSourceTitle(){add("PENDING");assertEquals(1,((Number)w.list(1,uid("teacher"),"100%","","ALL",0,1).get("total")).intValue());assertEquals(0,((Number)w.list(1,uid("teacher"),"_","","ALL",0,1).get("total")).intValue());assertEquals(1,((Number)w.list(1,uid("teacher"),"周同学","","ALL",0,1).get("total")).intValue());}
 @Test void statusAssignmentAndMineFilters(){add("DISPUTED");assertEquals(1,w.list(1,uid("teacher"),"","DISPUTED","ALL",1,1).get("total"));assertEquals(1,w.list(1,uid("peer"),"","","MINE",0,1).get("total"));assertEquals(0,w.list(1,uid("peer"),"","PENDING","MINE",0,1).get("total"));assertEquals(0,w.list(1,uid("teacher"),"","","ALL",999,1).get("total"));}
 @Test void queryValidationAndMissingDetail()throws Exception{for(String q:List.of("page=0","page=100001","assignmentId=-1","state=UNKNOWN","relation=EVERYTHING","q="+"x".repeat(81)))mvc.perform(get("/api/courses/1/evidence-workbench?"+q).with(user("teacher@example.test"))).andExpect(status().isBadRequest());mvc.perform(get("/api/evidence/99999/review").with(user("teacher@example.test"))).andExpect(status().isNotFound());}
 @Test void paginationAndDisputePriority(){for(int i=0;i<24;i++)add("PENDING");long d=add("DISPUTED");var r=w.list(1,uid("teacher"),"","","ALL",0,1);var rows=(List<Map<String,Object>>)r.get("items");assertEquals(20,rows.size());assertEquals(d,s.id(rows.getFirst(),"id"));assertEquals(6,((List<?>)w.list(1,uid("teacher"),"","","ALL",0,2).get("items")).size());}
 @Test void gradeFreezesActionsButHistoryRemains()throws Exception{var d=w.detail(1,uid("teacher"));assertEquals(true,d.get("locked"));assertEquals(false,d.get("can_verify"));assertFalse(((List<?>)d.get("records")).isEmpty());decide(1,"teacher","FAIL","已发分不可改判",((Number)d.get("record_count")).intValue(),422);}
 @Test void newVerificationSnapshotsRoleAndIsVisibleInHistory()throws Exception{long id=add("PENDING");decide(id,"student","PASS","对照教材第十页，材料支持此论断。",0,200);var r=domain.verifications(id,uid("teacher")).getFirst();assertEquals("STUDENT",r.get("verifier_role"));assertEquals("PASS",w.detail(id,uid("teacher")).get("state"));assertEquals(false,w.detail(id,uid("student")).get("can_verify"));}
 @Test void duplicatePeerAndStaleWindowDontAppend()throws Exception{long id=add("PENDING");decide(id,"student","PASS","已有核验",0,200);decide(id,"student","FAIL","同一人重复",1,409);decide(id,"teacher","FAIL","旧窗口",0,409);assertEquals(1,domain.verifications(id,uid("teacher")).size());}
 @Test void peerDisagreementCreatesDisputeTeacherResolvesWithoutDeleting()throws Exception{long id=add("PENDING");s.db.update("INSERT INTO course_member(course_id,user_id,role) VALUES(1,?,'STUDENT')",uid("outsider"));decide(id,"student","PASS","同伴判断支持",0,200);decide(id,"outsider","FAIL","另一同伴指出引文不完整",1,200);assertEquals("DISPUTED",w.detail(id,uid("teacher")).get("state"));decide(id,"teacher","FAIL","已对照原文，补足上下文后支持关系不成立。",2,200);var d=w.detail(id,uid("teacher"));assertEquals("FAIL",d.get("state"));assertEquals(3,((List<?>)d.get("records")).size());assertEquals("TEACHER",domain.verifications(id,uid("teacher")).getLast().get("verifier_role"));}
 @Test void teacherSnapshotSurvivesMembershipRemovalAndBlocksPeers()throws Exception{long id=add("PENDING");decide(id,"teacher","PASS","教师裁定",0,200);s.db.update("DELETE FROM course_member WHERE course_id=1 AND user_id=?",uid("teacher"));assertEquals(false,w.detail(id,uid("student")).get("can_verify"));decide(id,"student","FAIL","已裁定不可改",1,422);}
 @Test void teacherCanAppendCorrectionBeforeScoring()throws Exception{long id=add("PENDING");decide(id,"teacher","PASS","首次裁定",0,200);decide(id,"teacher","FAIL","复查来源后改判，保留此前依据",1,200);assertEquals(2,domain.verifications(id,uid("peer")).size());assertEquals("FAIL",w.detail(id,uid("peer")).get("state"));}
 @Test void legacyHistoryRoleIsNotInvented(){long id=add("PASS");s.db.update("INSERT INTO verification(evidence_id,verifier_id,verdict,reason,created_at) VALUES(?,?,'PASS','迁移前记录',?)",id,uid("student"),Store.now());assertNull(domain.verifications(id,uid("peer")).getFirst().get("verifier_role"));}
 @Test void csrfCountReasonAndVerdictValidation()throws Exception{long id=add("PENDING");String path="/api/evidence/"+id+"/decisions";mvc.perform(post(path).with(user("teacher@example.test")).contentType("application/json").content("{}")).andExpect(status().isForbidden());for(Object r:List.of(Map.of("verdict","PASS","reason","无版本"),Map.of("verdict","PASS","reason"," ","expectedCount",0),Map.of("verdict","PENDING","reason","非法结论","expectedCount",0),Map.of("verdict","PASS","reason","非法版本","expectedCount",-1)))mvc.perform(post(path).with(user("teacher@example.test")).with(csrf()).contentType("application/json").content(json.writeValueAsString(r))).andExpect(status().isBadRequest());assertEquals(0,domain.verifications(id,uid("teacher")).size());}
 @Test void todoAndDoneReflectActualEligibility()throws Exception{long id=add("PENDING");assertEquals(1,w.list(1,uid("student"),"","","TODO",0,1).get("total"));decide(id,"student","PASS","已对照",0,200);assertEquals(0,w.list(1,uid("student"),"","","TODO",0,1).get("total"));assertEquals(1,w.list(1,uid("student"),"","","DONE",0,1).get("total"));assertEquals(1,w.list(1,uid("teacher"),"","","TODO",0,1).get("total"));}
 @Test void removedMemberCannotReadOrDecide()throws Exception{long id=add("PENDING");s.db.update("DELETE FROM course_member WHERE course_id=1 AND user_id=?",uid("student"));mvc.perform(get("/api/evidence/"+id+"/review").with(user("student@example.test"))).andExpect(status().isForbidden());decide(id,"student","PASS","移出后禁止",0,403);}
 @Test void legacyVerifyEndpointStillFreezesAndSnapshots()throws Exception{long id=add("PENDING");mvc.perform(post("/api/evidence/"+id+"/verifications").with(user("student@example.test")).with(csrf()).contentType("application/json").content("{\"verdict\":\"PASS\",\"reason\":\"兼容核验接口\"}")).andExpect(status().isOk());assertEquals("STUDENT",domain.verifications(id,uid("teacher")).getFirst().get("verifier_role"));mvc.perform(post("/api/evidence/1/verifications").with(user("teacher@example.test")).with(csrf()).contentType("application/json").content("{\"verdict\":\"FAIL\",\"reason\":\"已冻结\"}")).andExpect(status().isUnprocessableEntity());}
}
